(()=>{
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
let draft=null;const saved=new Map();const fields=s=>[...s.querySelectorAll('input,select,textarea')].filter(e=>!e.closest('.country-picker'));try{draft=JSON.parse(localStorage.getItem('finsyndeo-whole-review-unified-draft-v1')||'null');if(draft&&draft.version<4)draft.screens.forEach(st=>{const screen=q('[data-screen="'+st.id+'"]');if(screen)fields(screen).forEach((e,i)=>{if(st.values[i])saved.set(e,st.values[i]);});});}catch(e){}
const input=(id,title,type='text',req=true)=>`<label class="field"><span>${title}</span><input id="${id}" type="${type}" ${req?'required':''} ${type==='number'?'min="0"':''}></label>`;
const sel=(id,title,opts)=>`<label class="field"><span>${title}</span><select id="${id}" required><option value="">Select…</option>${opts.map(x=>'<option>'+x+'</option>').join('')}</select></label>`;
const checks=(id,title,opts)=>`<fieldset id="${id}"><legend>${title}</legend><div class="checks">${opts.map(x=>'<label><input type="checkbox" value="'+x+'">'+x+'</label>').join('')}</div></fieldset>`;
const country=(id,title)=>`<div class="field"><span>${title}</span><input type="hidden" id="${id}"><div class="country-picker" id="${id}-picker"></div></div>`;
function hide(id){const e=q('#'+id);e.required=false;e.closest('.field').hidden=true;}
function licensor(){all('#licences label.field').filter(l=>!l.classList.contains('licensor')).forEach((l,i)=>{if(l.nextElementSibling?.classList.contains('licensor'))return;const el=document.createElement('label');el.className='field licensor';el.innerHTML='<span>Name of licensor / issuing authority</span><input id="licensor-'+i+'" required>';l.after(el);});}licensor();q('#add-licence').addEventListener('click',()=>setTimeout(licensor,0));
const crypto=all('#fi-type input').find(e=>e.value.includes('VASP'));crypto.value='Crypto-asset service provider (CASP)';crypto.parentElement.lastChild.textContent='Crypto-asset service provider (CASP)';
q('#fi-regulatory').closest('label').querySelector('span').textContent='Regulator';q('#fi-regulatory').minLength=0;q('#fi-regulatory').rows=1;
const reg=document.createElement('div');reg.innerHTML=input('fi-reference','Licence / registration number')+input('fi-permitted','Permitted activities');q('#fi-regulatory').closest('label').after(reg);
hide('fi-compliance-name');hide('fi-compliance-email');hide('fi-access');q('#fi-access-detail').hidden=true;q('#fi-access-text').required=false;
q('#fi-client-countries-picker').parentElement.hidden=true;
const regions=document.createElement('div');regions.innerHTML=checks('fi-regions','Main regions where underlying clients are based',['European Union (EU)','United Kingdom','United States','Canada','Latin America & Caribbean','Other Europe','Middle East','Asia (excluding Middle East)','Africa','Oceania']);q('#fi-client-countries-picker').parentElement.after(regions);
const services=q('#fi-services');services.hidden=true;const accounts=document.createElement('section');accounts.className='panel';accounts.innerHTML=checks('fi-account-model','Accounts required',['Operational account — own funds','Dedicated client-funds account'])+checks('fi-features','Additional capabilities',['Dedicated virtual IBANs for clients','Pooled / omnibus collection','API connectivity','SEPA / SEPA Instant','Bulk payments','FX conversion','Other']);q('[data-screen="32"] .panel').prepend(accounts);
const op=document.createElement('div');op.id='fi-operational-flows';op.innerHTML='<h2>Operational account — incoming & outgoing</h2>';const first=q('#fi-incoming-picker').parentElement;q('#fi-reporting').closest('label').after(op);op.append(first,q('#fi-outgoing-picker').parentElement,q('#fi-in-value').closest('.grid'));
const clients=document.createElement('div');clients.id='fi-client-flows';clients.innerHTML='<h2>Client-funds account — incoming & outgoing</h2>'+country('fi-client-in','Incoming countries — client funds')+country('fi-client-out','Outgoing countries — client funds')+'<div class="grid">'+input('fi-client-in-value','Expected incoming client funds per month','number')+input('fi-client-out-value','Expected outgoing client funds per month','number')+input('fi-client-in-count','Expected incoming client transactions per month','number')+input('fi-client-out-count','Expected outgoing client transactions per month','number')+'</div><p class="hint">Use the selected reporting currency. Do not include operational-account flows here.</p>';op.after(clients);
['fi-client-in','fi-client-out'].forEach(id=>initCountryPicker(q('#'+id+'-picker'),id,q('#'+id)));['fi-client-in-count','fi-client-out-count'].forEach(id=>q('#'+id).step='1');
const mlro=document.createElement('section');mlro.className='panel';mlro.innerHTML=sel('fi-mlro','MLRO arrangement',['Internal MLRO','External / outsourced MLRO','Not yet appointed'])+'<div id="fi-mlro-location" hidden>'+sel('fi-mlro-country','Where is the internal MLRO based?',countryNames)+'</div>';q('[data-screen="33"] .panel').prepend(mlro);q('#fi-mlro').onchange=()=>q('#fi-mlro-location').hidden=q('#fi-mlro').value!=='Internal MLRO';
const canada=document.createElement('section');canada.className='panel';canada.id='canadian-msb';canada.hidden=true;canada.innerHTML='<h2>Canadian MSB profile</h2>'+sel('msb-office','Do you have a staffed operating office in Canada?',['Yes — dedicated office','Yes — staffed shared office','Registered / mailing address only','No'])+sel('msb-director','Is at least one director based in Canada?',['Yes','No','Not applicable — no directors'])+sel('msb-boc','Bank of Canada PSP registration status',['Registered','Application submitted / listed as applicant','Not applied','Not in scope — subject to review'])+input('msb-boc-reference','Bank of Canada reference or register link (if available)','text',false)+input('msb-capital','Paid-up capital — EUR equivalent','number')+sel('msb-portal','Do clients have a personal portal or mobile app?',['Yes','In development','No'])+sel('msb-documents','Are your corporate and compliance documents available for later review?',['Yes','Partly','Not yet'])+sel('msb-cases','Can you provide six client due-diligence case files through a secure review process?',['Yes','Not yet — new business','No'])+sel('msb-portfolio','Can you provide a client portfolio breakdown by country, industry, legal form and risk level?',['Yes','Partly','Not yet'])+'<p class="hint">Document collection takes place later through an agreed secure process.</p>';q('[data-screen="30"] .panel').after(canada);
const casp=document.createElement('section');casp.className='panel';casp.id='casp-details';casp.hidden=true;casp.innerHTML='<h2>Crypto-asset services</h2>'+sel('casp-mica','MiCA status',['Authorised under MiCA','Eligible financial entity — Article 60 notification','Application pending','No MiCA authorisation','Not applicable — no EU services, subject to review'])+'<div id="casp-mica-detail" hidden>'+input('casp-authority','MiCA competent authority')+input('casp-reference','Authorisation / notification reference')+'</div>'+checks('casp-services','Crypto services',['Fiat-to-crypto / crypto-to-fiat exchange','Crypto-to-crypto exchange','Custody','Transfers','Brokerage / trading platform','Other'])+input('casp-assets','Crypto-assets and networks supported')+sel('casp-wallets','Do you support transfers to or from self-hosted wallets?',['Yes','No'])+sel('casp-travel','Travel Rule arrangements',['Implemented','In development','Not applicable — subject to review'])+sel('casp-chain','Blockchain transaction screening',['Implemented','In development','Not implemented']);canada.after(casp);
q('#casp-mica').onchange=()=>q('#casp-mica-detail').hidden=!['Authorised under MiCA','Eligible financial entity — Article 60 notification'].includes(q('#casp-mica').value);
function update(){const checked=all('#fi-type input:checked').map(e=>e.value);canada.hidden=!(checked.includes('Money services business (MSB)')&&q('#msb-country')?.value==='Canada');casp.hidden=!checked.some(v=>v.includes('CASP'));const opts=all('#fi-account-model input');op.hidden=!opts[0].checked;clients.hidden=!opts[1].checked;all('#fi-services input').forEach((e,i)=>e.checked=i===0?opts[0].checked:i===1?opts[1].checked:false);all('[data-screen="4"] label.field').filter(l=>l.textContent.includes('offer a personal account to a UBO')).forEach(l=>{if(q('#applicant').value==='institution')l.hidden=true;});}
const oldRefresh=refreshFlow;refreshFlow=function(){oldRefresh();update();};window.refreshFlow=refreshFlow;document.addEventListener('change',update);
const oldShow=showPage;showPage=function(n){if(q('#applicant').value==='institution'&&activeFlow().indexOf(n)>activeFlow().indexOf(currentPage)){if(currentPage===31&&!q('#fi-regions input:checked')){note('Please select at least one underlying-client region.');return;}if(currentPage===32){if(!q('#fi-account-model input:checked')){note('Choose an operational account, a client-funds account, or both.');return;}if(!clients.hidden&&(!q('#fi-client-in').value||!q('#fi-client-out').value)){note('Please select the incoming and outgoing countries for client funds.');return;}}if(currentPage===30&&!casp.hidden&&!q('#casp-services input:checked')){note('Please select the crypto-asset services you provide.');return;}}oldShow(n);};update();
if(draft&&draft.version<4){if(saved.has(crypto))saved.get(crypto).value=crypto.value;draft.screens=all('.screen').map(screen=>{const old=draft.screens.find(st=>st.id===screen.dataset.screen);return {id:screen.dataset.screen,values:fields(screen).map(e=>saved.get(e)||{value:e.value,checked:e.checked}),pickers:old?.pickers||[]};});draft.version=4;localStorage.setItem('finsyndeo-whole-review-unified-draft-v1',JSON.stringify(draft));}
})();
